const BulletAppearance* bullet_appearance(i32 type)noexcept{return type>=0&&type<i32(bullet_appearances.size())?&bullet_appearances[type]:nullptr;}
i32 bullet_cancellation(const BulletAppearance& p,i32 color,i32 previous,bool replacement)noexcept{
    switch(p.cancel_kind){case 0:return wrapping_add(wrapping_mul(color,2),4);case 1:{constexpr i32 scripts[]={4,8,12,16,20,24,28,34};return color>=0&&color<8?scripts[color]:previous;}case 2:return -1;case 3:return 16;case 4:return 6;case 5:return replacement?12:previous;case 6:return color>=0&&color<16?p.colors[color].cancel:previous;case 7:return 252;case 8:return 255;case 9:return 258;case 10:return 267;default:return previous;}
}
i32 bullet_animation_parameter(i32 type,i32 color,i32 parameter)noexcept{const auto* p=bullet_appearance(type);if(!p||color<0||color>=16||p->colors[0].sprite<0)return parameter;const auto& c=p->colors[color];switch(parameter){case 0:return c.sprite;case 1:return c.hit;case 2:return c.spawn;case 3:return c.cancel;default:return parameter;}}
